 static Panel SourceSection(string name,Button button,Label source){var panel=new Panel{Name=name,Dock=DockStyle.Fill,Padding=new Padding(4,2,4,2)};button.Dock=DockStyle.Left;button.Width=135;button.AutoSize=false;button.BackColor=SystemColors.Control;button.ForeColor=SystemColors.ControlText;button.UseVisualStyleBackColor=true;source.AutoSize=false;source.Dock=DockStyle.Fill;source.AutoEllipsis=true;source.TextAlign=ContentAlignment.MiddleLeft;panel.Controls.Add(source);panel.Controls.Add(button);return panel;}
 void RunSettingsAction(Action action){var window=settingsWindow;if(window!=null)window.Hide();try{action();}finally{if(window!=null&&!window.IsDisposed){window.Show(this);window.Activate();}}}
