 void UpdateShellStatus(){outputFormat.Text=(output==null?(int)width.Value:outW)+" × "+(output==null?(int)height.Value:outH)+" · "+(output==null?(int)fps.Value:activeProgramFps)+"p";RefreshOutputIndicators();string error=controlStatus.Text.Contains("ERRORE")?"Comandi Companion: errore (dettagli in Impostazioni)":companionStatus.Text.Contains("ERRORE")?"Notifiche Companion: errore (dettagli in Impostazioni)":audioNotice.ForeColor==Color.Firebrick?"Audio: errore (dettagli in Impostazioni)":null;serviceSummary.Text=error??("Companion: "+(settings.Companion.Enabled?"notifiche attive":"notifiche spente")+" · Comandi "+(settings.Companion.ControlEnabled?"attivi":"spenti")+" · Audio "+(ProgramAudio!=null?"Program attivo":"Program spento"));serviceSummary.ForeColor=error==null?Color.DimGray:Color.Firebrick;shellTips.SetToolTip(serviceSummary,controlStatus.Text+"\r\n"+companionStatus.Text+"\r\n"+audioNotice.Text);}
